from pathlib import Path

from podman_code_runner import PodmanCodeRunner


class FakeImages:
    def __init__(self):
        self.builds = 0
        self.fail = False

    def pull(self, image):
        if self.fail:
            raise RuntimeError("service unavailable")

    def build(self, *, path, tag, **kwargs):
        assert (Path(path) / "app.py").is_file()
        self.builds += 1
        return object(), []


class FakeContainer:
    def __init__(self, exit_code=0, running=False, stdout=b"", stderr=b""):
        self.exit_code = exit_code
        self.running = running
        self.stdout = stdout
        self.stderr = stderr
        self.killed = False
